sha.body:
 {
				enable: "chooseToUse",
				viewAs: {
					name: "sha",
					isCard: true,
				},
				viewAsFilter(player) {
					if (player.isLinked()) {
						return false;
					}
				},
				precontent() {
					player.link();
				},
				filterCard() {
					return false;
				},
				selectCard: -1,
				prompt: "横置武将牌，视为使用一张无视距离的杀",
				ai: {
					order() {
						return 3.15;
					},
					skillTagFilter(player, tag, arg) {
						if (arg === "respond") {
							return false;
						}
						if (player.isLinked()) {
							return false;
						}
					},
					respondSha: true,
				},
				mod: {
					targetInRange(card) {
						if (_status.event.skill === "xuanying_sha") {
							return true;
						}
					},
				},
			}

shan.body:
 {
				trigger: { player: ["chooseToRespondBegin", "chooseToUseBegin"] },
				filter(event, player) {
					if (!player.isLinked()) {
						return false;
					}
					if (event.responded) {
						return false;
					}
					if (!event.filterCard({ name: "shan" }, player, event)) {
						return false;
					}
					return true;
				},
				check(event, player) {
					if (get.damageEffect(player, event.player, player) >= 0) {
						return false;
					}
					return true;
				},
				content() {
					"step 0";
					player.link();
					"step 1";
					trigger.untrigger();
					trigger.responded = true;
					trigger.result = { bool: true, card: { name: "shan" } };
				},
				ai: {
					respondShan: true,
					target(card, player, target, current) {
						if (!player.isLinked() && current < 0) {
							return 1.5;
						}
						if (!target.hasFriend()) {
							return;
						}
						if (get.tag(card, "loseCard") && _status.currentPhase !== target && target.countCards("he")) {
							return [0.5, Math.max(2, target.countCards("h"))];
						}
						if (get.tag(card, "respondSha") || get.tag(card, "respondShan")) {
							if (get.attitude(player, target) > 0 && card.name === "juedou") {
								return;
							}
							return [0.5, target.countCards("h", "sha") + target.countCards("h", "shan")];
						}
					},
				},
			}

damage.body:
 {
				trigger: { player: "damageEnd" },
				filter(event, player) {
					return event.source && event.source.isAlive() && player.isLinked() && lib.filter.targetEnabled({ name: "sha" }, player, event.source);
				},
				check(event, player) {
					return get.effect(event.source, { name: "sha" }, player, player) > 0;
				},
				logTarget: "source",
				content() {
					"step 0";
					player.link();
					"step 1";
					player.useCard({ name: "sha" }, trigger.source);
				},
			}

use.body:
 {
				trigger: { player: "loseEnd" },
				direct: true,
				filter(event, player) {
					return _status.currentPhase !== player && player.isLinked() && event.cards && event.cards.length;
				},
				content() {
					"step 0";
					player
						.chooseTarget(get.prompt("xuanying"), function (card, player, target) {
							return lib.filter.targetEnabled({ name: "sha" }, player, target);
						})
						.set("ai", function (target) {
							return get.effect(target, { name: "sha" }, _status.event.player);
						})
						.set("autodelay", 0.5);
					"step 1";
					if (result.bool) {
						player.logSkill("xuanying");
						player.link();
						player.useCard({ name: "sha" }, result.targets, false);
					}
				},
			}

